ValidationRule.errorConditionFormula:
IF( ISNEW(), false,
IF ( RecordType.Id <> $Label.ABY_Meeting_notes_record_type, false, 
OR(
 AND( ISNULL( AB_Daily_rate__c ) , AB_Pretentions_salariales__c < 15000),
 AND( ISNULL( AB_Daily_rate__c ) , ISNULL( AB_Pretentions_salariales__c)),
 AND( NOT(ISNULL( AB_Daily_rate__c )) , AB_Pretentions_salariales__c < 15000)
)
)
)
